// ===== НАСТРОЙКИ =====
// ID Google-таблицы «Налоги ИП МК» (из ссылки на таблицу)
const SHEET_ID = '1epYsyQoB1FgexKBqlWgGdriKxeO86hXDe0_VYL9EzdY';
// Кому бот отвечает. Узнать свой chat id: напишите боту что угодно, он пришлёт номер.
const ALLOWED_CHAT_IDS = [];
// Модель OpenAI с распознаванием изображений
const MODEL = 'gpt-5.5';
// =====================

const m = $json.message || {};
const chatId = String(m.chat?.id ?? '');
let route = 'command';
let fileId = null;
let fileName = '';

if (m.photo && m.photo.length) {
  route = 'check';
  fileId = m.photo[m.photo.length - 1].file_id; // самое большое разрешение
} else if (m.document) {
  const mime = String(m.document.mime_type || '').toLowerCase();
  fileName = m.document.file_name || '';
  const name = fileName.toLowerCase();
  fileId = m.document.file_id;
  if (mime.startsWith('image/')) route = 'check';
  else if (mime === 'application/pdf' || name.endsWith('.pdf')) route = 'pdf';
  else if (name.endsWith('.xlsx') || name.endsWith('.xls') || mime.includes('spreadsheet') || mime.includes('excel')) route = 'xlsx';
  else route = 'unknown';
}

// Запуск по расписанию (узел «Каждый понедельник»): напоминание первому из списка
if (!$json.message) {
  return [{ json: { chatId: String(ALLOWED_CHAT_IDS[0] || ''), route: 'reminder', fileId: null, fileName: '', text: '', sheet: SHEET_ID, model: MODEL } }];
}

if (!ALLOWED_CHAT_IDS.includes(chatId)) route = 'denied';

return [{
  json: {
    chatId,
    route,
    fileId,
    fileName,
    text: String(m.text || m.caption || '').trim(),
    sheet: SHEET_ID,
    model: MODEL,
  },
}];

// Готовит запрос в OpenAI: фото чека -> JSON с реквизитами
const item = $input.first();
if (!item.binary || !item.binary.data) throw new Error('Telegram не отдал файл чека');
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const cfg = $('Разбор сообщения').first().json;
const mimeType = String(item.binary.data.mimeType || '');
const mime = mimeType.startsWith('image/') ? mimeType : 'image/jpeg';

const prompt = `Ты бухгалтер ИП в Казахстане. На фото один или несколько фискальных чеков или накладных. Покупатель: ИП «МК», ИИН 870727350990.
Верни JSON строго такого вида:
{"docs":[{"date":"YYYY-MM-DD","seller":"название продавца","seller_bin":"БИН/ИИН продавца, 12 цифр, или пустая строка","items":"кратко что куплено, по-русски, до 80 символов","total":12345.67,"fp":"фискальный признак (ФП/ФБ), а если его нет, номер чека или накладной","buyer_iin":true,"readable":true}]}
Правила:
- total: итоговая сумма документа (ИТОГ / ЖИЫНЫ / БАРЛЫҒЫ / Сумма оплаты). Не сумма внесённых наличных и не сдача.
- buyer_iin: true, только если в документе напечатан ИИН покупателя 870727350990.
- Если документ не читается или не видно суммы и даты, readable=false.
- Ничего не придумывай. Одна запись на один документ.`;

return [{
  json: {
    body: {
      model: cfg.model,
      response_format: { type: 'json_object' },
      messages: [{
        role: 'user',
        content: [
          { type: 'text', text: prompt },
          { type: 'image_url', image_url: { url: `data:${mime};base64,${buf.toString('base64')}` } },
        ],
      }],
    },
  },
}];

// Достаёт список документов из ответа OpenAI
const content = $json.choices?.[0]?.message?.content || '';
let docs = [];
let error = '';
try {
  docs = JSON.parse(content).docs || [];
} catch (e) {
  error = $json.error?.message || 'OpenAI не вернул данные';
}
return [{ json: { docs, error } }];

// Сверяет распознанные чеки с листом «Расходы» и готовит строки для добавления
const { docs } = $('Чеки из ответа').first().json;
const ranges = $json.valueRanges || [];
const rows = ranges[0]?.values || [];
const startRaw = ranges[1]?.values?.[0]?.[0] || '';

const toIso = (s) => {
  const m = String(s).match(/(\d{2})\.(\d{2})\.(\d{4})/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : String(s);
};
const digits = (s) => String(s || '').replace(/\D/g, '');
const num = (s) => parseFloat(String(s).replace(/[\s ]/g, '').replace(',', '.')) || 0;

const startIso = toIso(startRaw);
const knownFp = new Set(rows.map((r) => digits(r[5])).filter(Boolean));
const knownDateSum = new Set(rows.map((r) => `${toIso(r[0])}|${Math.round(num(r[4]))}`));

const values = [];
const added = [];
const dups = [];
const bad = [];

for (const d of docs) {
  const total = Number(d.total);
  if (!d.readable || !total || !/^\d{4}-\d{2}-\d{2}$/.test(String(d.date || ''))) {
    bad.push(d);
    continue;
  }
  const fp = digits(d.fp);
  const dateSum = `${d.date}|${Math.round(total)}`;
  if ((fp && knownFp.has(fp)) || (!fp && knownDateSum.has(dateSum))) {
    dups.push(d);
    continue;
  }
  if (fp) knownFp.add(fp);
  knownDateSum.add(dateSum);

  const [y, mo, da] = d.date.split('-');
  values.push([
    `${da}.${mo}.${y}`,
    d.seller || '',
    d.seller_bin ? "'" + digits(d.seller_bin) : '',
    d.items || '',
    total,
    "'" + String(d.fp || ''),
    d.buyer_iin ? 'да' : 'нет',
    'бот',
  ]);
  added.push({ ...d, total, outOfPeriod: Boolean(startIso && d.date < startIso) });
}

return [{ json: { skip: values.length === 0, body: { values }, added, dups, bad } }];

// Готовит запрос в OpenAI: PDF-выписка Kaspi -> JSON с поступлениями.
// PDF отправляется файлом целиком: так модель видит колонки «Дебет» и «Кредит» и не путает их.
const item = $input.first();
if (!item.binary || !item.binary.data) throw new Error('Telegram не отдал файл выписки');
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const cfg = $('Разбор сообщения').first().json;

const prompt = `Это банковская выписка Kaspi Bank по счёту ИП. Верни JSON строго такого вида:
{"period_from":"YYYY-MM-DD","period_to":"YYYY-MM-DD","last_operation":"YYYY-MM-DD","opening_balance":0,"closing_balance":0,"total_debit":0,"total_credit":0,"credit_count":0,"credits":[{"doc":"номер документа","date":"YYYY-MM-DD","sender":"название отправителя без БИН/ИИН","amount":0,"knp":"КНП","purpose":"назначение платежа, кратко, до 80 символов"}]}
Правила:
- last_operation: «Дата последнего движения» из шапки.
- credits: все операции с суммой в колонке «Кредит» (поступления на счёт). Списания не включай.
- total_debit, total_credit и credit_count бери из строк «Итого обороты» и «Итого операций за период» в конце выписки.
- Суммы переписывай точно, без округления, числом.`;

return [{
  json: {
    body: {
      model: cfg.model,
      reasoning_effort: 'low',
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: prompt },
        {
          role: 'user',
          content: [{
            type: 'file',
            file: { filename: 'statement.pdf', file_data: `data:application/pdf;base64,${buf.toString('base64')}` },
          }],
        },
      ],
    },
  },
}];

// Достаёт данные выписки из ответа OpenAI
const content = $json.choices?.[0]?.message?.content || '';
let st = null;
let error = '';
try {
  st = JSON.parse(content);
} catch (e) {
  error = $json.error?.message || 'OpenAI не вернул данные';
}
if (!st || !Array.isArray(st.credits)) {
  st = { credits: [] };
  error = error || 'в выписке не нашлось поступлений';
}
return [{ json: { st, error } }];

// Отбирает новые поступления за период и готовит строки для листов «Доходы» и «Выписки»
const { st, error } = $('Поступления из ответа').first().json;
const ranges = $json.valueRanges || [];
const rows = ranges[0]?.values || [];
const startRaw = ranges[1]?.values?.[0]?.[0] || '';

const toIso = (s) => {
  const m = String(s).match(/(\d{2})\.(\d{2})\.(\d{4})/);
  return m ? `${m[3]}-${m[2]}-${m[1]}` : String(s);
};
const ru = (iso) => (iso && /^\d{4}-\d{2}-\d{2}$/.test(iso) ? iso.split('-').reverse().join('.') : '');
const startIso = toIso(startRaw);
const known = new Set(rows.map((r) => String(r[5] || '').trim()));

const values = [];
const added = [];
const skipped = [];

for (const c of st.credits || []) {
  const amount = Number(c.amount);
  if (!amount || !/^\d{4}-\d{2}-\d{2}$/.test(String(c.date || ''))) continue;
  if (startIso && c.date < startIso) continue; // до начала периода, уже посчитано ранее
  const purpose = String(c.purpose || '');
  const p = purpose.toLowerCase();
  if (String(c.knp) === '342' || p.includes('собственных средств')) {
    skipped.push({ ...c, amount, why: 'перевод своих денег' });
    continue;
  }
  if (p.includes('отмена') || p.includes('возврат')) {
    skipped.push({ ...c, amount, why: 'возврат покупки' });
    continue;
  }
  const key = `${String(c.doc || '').trim()}|${c.date}|${amount}`;
  if (known.has(key)) continue; // уже есть в таблице
  known.add(key);
  values.push([ru(c.date), c.sender || '', amount, purpose, "'" + String(c.doc || ''), "'" + key]);
  added.push({ ...c, amount });
}

// Сверка: все поступления из выписки должны совпасть с итоговой строкой «Итого обороты»
const sum = added.reduce((s, c) => s + c.amount, 0);
const round2 = (x) => Math.round(Number(x) * 100) / 100;
const credits = st.credits || [];
const allCredits = round2(credits.reduce((s, c) => s + Number(c.amount || 0), 0));
const problems = [];
if (typeof st.total_credit !== 'number' || allCredits !== round2(st.total_credit)) {
  problems.push(`сумма поступлений ${allCredits} не равна итогу по кредиту ${st.total_credit}`);
}
if (typeof st.credit_count === 'number' && credits.length !== st.credit_count) {
  problems.push(`найдено ${credits.length} поступлений, а в итоге выписки ${st.credit_count}`);
}
if ([st.opening_balance, st.closing_balance, st.total_debit, st.total_credit].every((x) => typeof x === 'number')
  && round2(st.opening_balance + st.total_credit - st.total_debit) !== round2(st.closing_balance)) {
  problems.push('остатки не сходятся');
}
const invalid = Boolean(error) || problems.length > 0;
const check = invalid ? 'НЕ сходится' : 'сходится';
const today = $now.setZone('Asia/Almaty').toFormat('dd.MM.yyyy');
const lastOp = st.last_operation || st.period_to || '';

return [{
  json: {
    invalid,
    problems,
    skip: values.length === 0,
    body: { values },
    logBody: { values: [[today, ru(st.period_from), ru(lastOp), added.length, sum, check]] },
    added,
    skipped,
    sum,
    check,
    periodFrom: ru(st.period_from),
    lastOp: ru(lastOp),
    error,
  },
}];

// Собирает ответные сообщения в Telegram (HTML-разметка)
const cfg = $('Разбор сообщения').first().json;
const rows = $json.valueRanges?.[0]?.values || $json.values || [];
const get = (label) => (rows.find((r) => r[0] === label) || [])[1] || '—';
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => Math.round(Number(n)).toLocaleString('ru-RU').replace(/ /g, ' ') + ' ₸';
const ru = (iso) => (iso && /^\d{4}-\d{2}-\d{2}$/.test(iso) ? iso.split('-').reverse().join('.') : esc(iso));
const safe = (name) => {
  try {
    return $(name).first().json;
  } catch (e) {
    return null;
  }
};

const tax = get('Итого к уплате, ₸');
const taxLine = `💰 Налог к уплате сейчас: <b>${esc(tax)} ₸</b>`;
const sheetUrl = `https://docs.google.com/spreadsheets/d/${cfg.sheet}/edit`;

const pad = (label, value) => label.padEnd(14, ' ') + String(value).padStart(13, ' ') + ' ₸';
const summary = [
  `<b>📊 Налог ИП «МК» с ${esc(get('Начало периода'))}</b>`,
  '<pre>' + [
    pad('Доходы', get('Доходы за период, ₸')),
    pad('Расходы', get('Расходы по чекам за период, ₸')),
    pad('База', get('Налогооблагаемая база, ₸')),
    pad('ИПН', get('ИПН, ₸')),
    pad('Ранее', '+' + get('Ранее начислено по уведомлению, ₸')),
  ].map(esc).join('\n') + '</pre>',
  `<b>Итого к уплате: ${esc(tax)} ₸</b>`,
  `Чеков за период: ${esc(get('Чеков за период'))}, из них без вашего ИИН: ${esc(get('Чеков без ИИН покупателя'))}`,
  '',
  '<b>📌 Дальше пришлите:</b>',
  `• выписку Kaspi с <b>${esc(get('Следующая выписка с'))}</b>`,
  `• чеки с <b>${esc(get('Следующие чеки с'))}</b>`,
  '',
  `<a href="${sheetUrl}">Открыть таблицу</a>`,
].join('\n');

const messages = [];

if (cfg.route === 'check') {
  const r = safe('Новые чеки') || { added: [], dups: [], bad: [] };
  const parsed = safe('Чеки из ответа') || {};
  const lines = [];
  for (const d of r.added) {
    let line = `✅ ${esc(d.seller)}: ${money(d.total)} (${ru(d.date)})`;
    if (d.outOfPeriod) line += ', дата до начала периода, в налог не входит';
    else if (!d.buyer_iin) line += ', без вашего ИИН';
    lines.push(line);
  }
  for (const d of r.dups) lines.push(`↩️ Уже в таблице: ${esc(d.seller)}, ${money(d.total)} (${ru(d.date)})`);
  if (r.bad.length || (!r.added.length && !r.dups.length)) {
    lines.push('⚠️ Не смог прочитать чек. Переснимите ближе, ровно и при хорошем свете, чтобы были видны дата, итог и ФП.');
  }
  if (parsed.error) lines.push(`Ошибка распознавания: ${esc(parsed.error)}`);
  lines.push('', taxLine);
  messages.push(lines.join('\n'));
} else if (cfg.route === 'pdf' && (safe('Новые поступления') || {}).invalid) {
  const r = safe('Новые поступления');
  messages.push([
    '⚠️ <b>Выписку не записал</b>: сверка с итогами выписки не сошлась.',
    ...r.problems.map((p) => `• ${esc(p)}`),
    ...(r.error ? [`• ${esc(r.error)}`] : []),
    '',
    'Пришлите PDF ещё раз. Если повторится, проверьте, что это полная выписка Kaspi со строкой «Итого обороты».',
    '',
    taxLine,
  ].join('\n'));
} else if (cfg.route === 'pdf') {
  const r = safe('Новые поступления') || { added: [], skipped: [], sum: 0 };
  const lines = [`📄 <b>Выписка принята</b>: ${esc(r.periodFrom)} – ${esc(r.lastOp)}`];
  if (r.added.length) {
    lines.push(`Новых поступлений: ${r.added.length} на ${money(r.sum)}`);
    for (const c of r.added) lines.push(`• ${ru(c.date)} ${esc(c.sender)}: ${money(c.amount)}`);
  } else {
    lines.push('Новых поступлений нет (всё уже было в таблице или вне периода).');
  }
  for (const c of r.skipped) lines.push(`➖ Не доход (${esc(c.why)}): ${ru(c.date)} ${money(c.amount)}`);
  lines.push('✔️ Сверка с «Итого обороты» сошлась.', '', taxLine);
  messages.push(lines.join('\n'));
  messages.push(summary);
} else if (cfg.route === 'reminder') {
  messages.push([
    '⏰ <b>Напоминание: пора внести документы за неделю</b>',
    `• PDF-выписку Kaspi с <b>${esc(get('Следующая выписка с'))}</b>`,
    `• чеки с <b>${esc(get('Следующие чеки с'))}</b>`,
    '',
    taxLine,
  ].join('\n'));
} else {
  const t = cfg.text.toLowerCase();
  if (t.startsWith('/start') || t.startsWith('/help') || t === 'помощь') {
    messages.push([
      '👋 Я считаю налог ИП «МК».',
      '• Пришлите фото чека или накладной, и я внесу расход.',
      '• Пришлите PDF-выписку Kaspi, и я внесу поступления (сверю их с «Итого обороты»).',
      '• Команда /итог покажет текущий расчёт.',
    ].join('\n'));
  } else if (cfg.route === 'xlsx') {
    messages.push('Excel-выписку я не принимаю: в ней нет итоговой строки для сверки. Выгрузите выписку Kaspi в PDF и пришлите сюда.');
  } else if (cfg.route === 'unknown') {
    messages.push('Этот файл я не понимаю. Пришлите фото чека или PDF-выписку Kaspi.');
  }
  messages.push(summary);
}

return messages.map((text) => ({ json: { chatId: cfg.chatId, text } }));
